  <div class="vc-tabs" role="tablist"><button type="button" class="vc-tab active" data-tab-target="queue" aria-selected="true">Delivery queue</button><button type="button" class="vc-tab" data-tab-target="dispatch" aria-selected="false">Manual dispatch</button><button type="button" class="vc-tab" data-tab-target="coverage" aria-selected="false">Pan-India coverage</button><button type="button" class="vc-tab" data-tab-target="rates" aria-selected="false">Rate rules</button><button type="button" class="vc-tab" data-tab-target="calculator" aria-selected="false">Rate calculator</button><button type="button" class="vc-tab" data-tab-target="attempts" aria-selected="false">Attempts & RTO</button></div>
  <section data-tab-panel="queue"><div class="vc-grid four"><article class="vc-card vc-stat"><span class="vc-stat-label">Ready to dispatch</span><div class="vc-stat-value">5</div></article><article class="vc-card vc-stat"><span class="vc-stat-label">In transit</span><div class="vc-stat-value">18</div></article><article class="vc-card vc-stat"><span class="vc-stat-label">Out for delivery</span><div class="vc-stat-value">4</div></article><article class="vc-card vc-stat"><span class="vc-stat-label">Failed attempts</span><div class="vc-stat-value">3</div></article></div><div class="vc-card mt-3"><div class="vc-card-head"><h2>Manual delivery queue</h2><span class="vc-help">All status updates are entered by the vendor</span></div><div class="vc-table-wrap"><table class="vc-table"><thead><tr><th>Order</th><th>Destination</th><th>Method</th><th>Expected</th><th>Status</th><th>Last update</th><th>Action</th></tr></thead><tbody><tr><td>CI-84718-V1</td><td>Delhi 110001</td><td>Not assigned</td><td>22 Sep</td><td><span class="vc-status warning">Ready for dispatch</span></td><td>Packed 10:15 AM</td><td><button type="button" class="vc-btn small primary" data-tab-jump="dispatch">Dispatch</button></td></tr><tr><td>CI-84712-V1</td><td>Pune 411001</td><td>Local courier</td><td>19 Sep</td><td><span class="vc-status info">In transit</span></td><td>Pune facility · 8:40 AM</td><td><button type="button" class="vc-btn small" data-open-dialog="update-dialog">Update</button></td></tr><tr><td>CI-84711-V1</td><td>Jaipur 302004</td><td>Vendor employee</td><td>Today</td><td><span class="vc-status info">Out for delivery</span></td><td>Customer contacted</td><td><button type="button" class="vc-btn small" data-open-dialog="outcome-dialog">Outcome</button></td></tr></tbody></table></div></div></section>
  <section data-tab-panel="dispatch" id="dispatch" hidden><form class="vc-card" data-frontend-form="manual-dispatch" data-success="Manual dispatch details validated. No courier booking was performed."><div class="vc-card-head"><h2>Dispatch CI-84718-V1</h2><span class="vc-status warning">Vendor-managed</span></div><div class="vc-card-body"><div class="vc-callout">This form records a delivery that the vendor has already arranged. It does not contact Shiprocket or automatically book a courier.</div><div class="vc-form-grid mt-3">
    <div class="vc-field"><label for="dispatch-method">Delivery method <span class="vc-required">*</span></label><select class="vc-select" id="dispatch-method" name="method" required><option value="">Choose method</option><option>Vendor self-delivery</option><option>Vendor employee</option><option>Local courier arranged by vendor</option><option>National courier arranged by vendor</option><option>Customer pickup</option><option>Other</option></select></div>
    <div class="vc-field"><label for="service-name">Service/courier name <span class="vc-required">*</span></label><input class="vc-input" id="service-name" name="service_name" required maxlength="100"></div>
    <div class="vc-field"><label for="delivery-reference">Delivery reference</label><input class="vc-input" id="delivery-reference" name="reference" maxlength="80"><span class="vc-help">Optional; AWB is not required.</span></div>
    <div class="vc-field"><label for="tracking-url">Tracking URL</label><input class="vc-input" id="tracking-url" name="tracking_url" type="url" maxlength="300"></div>
    <div class="vc-field"><label for="agent-name">Delivery person name</label><input class="vc-input" id="agent-name" name="agent_name" maxlength="100"></div>
    <div class="vc-field"><label for="agent-phone">Delivery person phone</label><input class="vc-input" id="agent-phone" name="agent_phone" inputmode="numeric" data-indian-phone maxlength="10"></div>
    <div class="vc-field"><label for="dispatch-time">Dispatch date/time <span class="vc-required">*</span></label><input class="vc-input" id="dispatch-time" name="dispatch_time" type="datetime-local" required></div>
    <div class="vc-field"><label for="expected-date">Expected delivery <span class="vc-required">*</span></label><input class="vc-input" id="expected-date" name="expected_date" type="date" required></div>
    <div class="vc-field"><label for="delivery-fee">Delivery charge recorded (₹)</label><input class="vc-input" id="delivery-fee" name="delivery_fee" type="number" data-money min="0" max="100000" step="0.01" required></div>
    <div class="vc-field"><label for="package-count">Package count</label><input name="package-count" class="vc-input" id="package-count" type="number" min="1" max="100" value="1" required></div>
    <div class="vc-field full"><label for="dispatch-note">Customer-visible note</label><textarea class="vc-textarea" id="dispatch-note" name="note" maxlength="500"></textarea></div>
    <div class="vc-field full"><label for="dispatch-proof">Dispatch receipt/photo</label><input name="dispatch-proof" class="vc-input" id="dispatch-proof" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" data-max-bytes="5242880"></div>
    <div class="vc-field full"><label class="vc-check"><input name="vc-delivery-input-13" id="vc-delivery-input-13" type="checkbox" required> I confirm the package has physically been handed over for delivery and the entered details are accurate.</label></div>
    <div class="vc-field full"><label class="vc-check"><input name="vc-delivery-input-14" id="vc-delivery-input-14" type="checkbox" checked> Notify the customer after saving this update.</label></div>
  </div><div class="vc-form-actions"><button class="vc-btn" type="button" data-demo-action="Print address label">Address label</button><button class="vc-btn primary" type="submit">Confirm dispatch</button></div></div></form></section>
  <section data-tab-panel="coverage" hidden><form class="vc-card" data-frontend-form="coverage" data-success="Pan-India coverage rules validated and saved locally as non-sensitive demo preferences."><div class="vc-card-head"><h2>Serviceability coverage</h2><span class="vc-status success">Pan India enabled</span></div><div class="vc-card-body"><div class="vc-form-grid"><div class="vc-field"><label for="coverage-mode">Coverage mode</label><select class="vc-select" id="coverage-mode" name="coverage_mode" required><option value="all_india">All India with exclusions</option><option value="states">Selected states/UTs</option><option value="pincodes">Selected PIN codes</option><option value="custom">Custom combination</option></select></div><div class="vc-field"><label for="origin-pin">Primary dispatch PIN</label><input class="vc-input" id="origin-pin" name="origin_pin" data-pincode required maxlength="6" value="302001"></div><div class="vc-field full"><label for="excluded-states">Excluded states/UTs</label><select class="vc-select" id="excluded-states" name="excluded_states" multiple size="6"><option>Andaman and Nicobar Islands</option><option>Andhra Pradesh</option><option>Arunachal Pradesh</option><option>Assam</option><option>Bihar</option><option>Chandigarh</option><option>Chhattisgarh</option><option>Dadra and Nagar Haveli and Daman and Diu</option><option>Delhi</option><option>Goa</option><option>Gujarat</option><option>Haryana</option><option>Himachal Pradesh</option><option>Jammu and Kashmir</option><option>Jharkhand</option><option>Karnataka</option><option>Kerala</option><option>Ladakh</option><option selected>Lakshadweep</option><option>Madhya Pradesh</option><option>Maharashtra</option><option>Manipur</option><option>Meghalaya</option><option>Mizoram</option><option>Nagaland</option><option>Odisha</option><option>Puducherry</option><option>Punjab</option><option>Rajasthan</option><option>Sikkim</option><option>Tamil Nadu</option><option>Telangana</option><option>Tripura</option><option>Uttar Pradesh</option><option>Uttarakhand</option><option>West Bengal</option></select></div><div class="vc-field full"><label for="excluded-pins">Excluded PIN codes</label><textarea class="vc-textarea" id="excluded-pins" name="excluded_pincodes" pattern="[0-9,\s-]*" placeholder="One PIN per line or comma-separated">682555</textarea></div><div class="vc-field"><label for="pin-import">Import serviceable/excluded PIN list</label><input name="pin-import" class="vc-input" id="pin-import" type="file" accept=".csv,text/csv" data-max-bytes="5242880"></div><div class="vc-field"><label>PIN-code tester</label><div data-pincode-checker><div class="vc-toolbar"><input name="vc-delivery-input-20" id="vc-delivery-input-20" class="vc-input" data-pincode maxlength="6" inputmode="numeric" placeholder="Enter PIN"><button class="vc-btn" type="button" data-check-pincode>Check</button></div><div data-pincode-result></div></div></div></div><div class="vc-form-actions"><button class="vc-btn" type="button" data-demo-action="Download PIN code template">CSV template</button><button class="vc-btn primary" type="submit">Save coverage</button></div></div></form></section>
  <section data-tab-panel="rates" hidden><div class="vc-card"><div class="vc-card-head"><h2>Delivery price rules</h2><button type="button" class="vc-btn primary" data-open-dialog="rate-dialog">Add rule</button></div><div class="vc-table-wrap"><table class="vc-table"><thead><tr><th>Rule</th><th>Scope</th><th>Calculation</th><th>Charge</th><th>Free above</th><th>ETA</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr><td>Jaipur Local</td><td>Selected Jaipur PINs</td><td>Flat</td><td>₹30</td><td>₹599</td><td>1–2 days</td><td><span class="vc-status success">Active</span></td><td><button type="button" class="vc-btn small" data-demo-action="Edit rate rule">Edit</button></td></tr><tr><td>Same State</td><td>Rajasthan</td><td>Flat</td><td>₹59</td><td>₹999</td><td>2–4 days</td><td><span class="vc-status success">Active</span></td><td><button type="button" class="vc-btn small" data-demo-action="Edit rate rule">Edit</button></td></tr><tr><td>Pan-India Standard</td><td>All serviceable locations</td><td>Weight slab</td><td>From ₹99</td><td>₹1,499</td><td>5–9 days</td><td><span class="vc-status success">Active</span></td><td><button type="button" class="vc-btn small" data-demo-action="Edit rate rule">Edit</button></td></tr></tbody></table></div></div></section>
  <section data-tab-panel="calculator" hidden><form class="vc-card" data-rate-calculator><div class="vc-card-head"><h2>Chargeable-weight calculator</h2></div><div class="vc-card-body"><div class="vc-form-grid"><div class="vc-field"><label for="vc-delivery-input-21">Dead weight (kg)</label><input id="vc-delivery-input-21" class="vc-input" name="weight" type="number" min="0" step="0.01" value="0.5"></div><div class="vc-field"><label for="vc-delivery-input-22">Volumetric divisor</label><input id="vc-delivery-input-22" class="vc-input" name="divisor" type="number" min="1" value="5000"></div><div class="vc-field"><label for="vc-delivery-input-23">Length (cm)</label><input id="vc-delivery-input-23" class="vc-input" name="length" type="number" min="0" value="20"></div><div class="vc-field"><label for="vc-delivery-input-24">Width (cm)</label><input id="vc-delivery-input-24" class="vc-input" name="width" type="number" min="0" value="15"></div><div class="vc-field"><label for="vc-delivery-input-25">Height (cm)</label><input id="vc-delivery-input-25" class="vc-input" name="height" type="number" min="0" value="10"></div></div><div class="vc-grid three mt-3"><div class="vc-card vc-stat"><span class="vc-stat-label">Volumetric weight</span><div class="vc-stat-value" data-volumetric>0.60 kg</div></div><div class="vc-card vc-stat"><span class="vc-stat-label">Chargeable weight</span><div class="vc-stat-value" data-chargeable>0.60 kg</div></div><div class="vc-card vc-stat"><span class="vc-stat-label">Estimated standard rate</span><div class="vc-stat-value" data-estimated-rate>₹149.00</div></div></div></div></form></section>
