<dialog class="vc-dialog" id="rate-dialog"><div class="vc-dialog-head"><h2>Add delivery rate rule</h2><button type="button" class="vc-btn small" data-close-dialog>Close</button></div><form class="vc-dialog-body" data-frontend-form="delivery-rate" data-success="Rate rule validated and saved as a frontend demo preference."><div class="vc-form-grid"><div class="vc-field"><label for="vc-delivery-input-26">Rule name</label><input id="vc-delivery-input-26" class="vc-input" name="rule_name" required maxlength="80"></div><div class="vc-field"><label for="vc-delivery-input-27">Scope</label><input id="vc-delivery-input-27" class="vc-input" name="scope" required maxlength="80" placeholder="State, city, zone, or PIN group"></div><div class="vc-field"><label for="vc-delivery-input-28">Charge (₹)</label><input id="vc-delivery-input-28" class="vc-input" name="charge" type="number" data-money required min="0" max="100000" step="0.01"></div><div class="vc-field"><label for="vc-delivery-input-29">Free above (₹)</label><input id="vc-delivery-input-29" class="vc-input" name="free_above" type="number" data-money min="0" max="10000000" step="0.01" value="0"></div><div class="vc-field"><label for="vc-delivery-input-30">Minimum days</label><input name="vc-delivery-input-30" id="vc-delivery-input-30" class="vc-input" type="number" min="0" max="90" required></div><div class="vc-field"><label for="vc-delivery-input-31">Maximum days</label><input name="vc-delivery-input-31" id="vc-delivery-input-31" class="vc-input" type="number" min="0" max="180" required></div></div><div class="vc-form-actions"><button class="vc-btn primary" type="submit">Validate and save rule</button></div></form></dialog>
<dialog class="vc-dialog" id="update-dialog"><div class="vc-dialog-head"><h2>Add manual delivery update</h2><button type="button" class="vc-btn small" data-close-dialog>Close</button></div><form class="vc-dialog-body" data-frontend-form="delivery-update" data-success="Delivery update validated and queued for customer notification."><div class="vc-form-grid"><div class="vc-field"><label for="update-status">Status</label><select class="vc-select" id="update-status" name="update_status" required><option value="">Choose status</option><option>Picked up</option><option>In transit</option><option>Reached destination city</option><option>Out for delivery</option><option>Customer contacted</option><option>Delivery rescheduled</option><option>Delivery attempted</option><option>Returning to vendor</option><option>Returned to vendor</option></select></div><div class="vc-field"><label for="update-time">Date/time</label><input class="vc-input" id="update-time" name="update_time" type="datetime-local" required></div><div class="vc-field full"><label for="update-location">Location</label><input class="vc-input" id="update-location" name="update_location" required maxlength="160"></div><div class="vc-field full"><label for="update-note">Customer-visible update</label><textarea class="vc-textarea" id="update-note" name="update_note" required minlength="10" maxlength="500"></textarea></div><div class="vc-field full"><label for="update-evidence">Supporting evidence</label><input class="vc-input" id="update-evidence" name="update_evidence" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" data-max-bytes="5242880"></div><div class="vc-field full"><label class="vc-check"><input name="notify_customer" type="checkbox" checked> Notify customer after saving.</label></div></div><div class="vc-form-actions"><button class="vc-btn primary" type="submit">Validate update</button></div></form></dialog>
<dialog class="vc-dialog" id="outcome-dialog"><div class="vc-dialog-head"><h2>Record delivery outcome</h2><button type="button" class="vc-btn small" data-close-dialog>Close</button></div><form class="vc-dialog-body" data-frontend-form="delivery-outcome" data-success="Delivery outcome and proof fields validated."><div class="vc-form-grid"><div class="vc-field"><label for="outcome">Outcome</label><select class="vc-select" id="outcome" name="outcome" required><option value="">Choose outcome</option><option>Delivered</option><option>Delivery failed</option><option>Customer refused</option><option>Re-delivery scheduled</option></select></div><div class="vc-field"><label for="outcome-time">Date/time</label><input class="vc-input" id="outcome-time" name="outcome_time" type="datetime-local" required></div><div class="vc-field"><label for="recipient-name">Recipient name</label><input class="vc-input" id="recipient-name" name="recipient_name" maxlength="100"></div><div class="vc-field"><label for="recipient-type">Recipient type</label><select class="vc-select" id="recipient-type" name="recipient_type"><option>Customer</option><option>Family member</option><option>Security/reception</option><option>Neighbour</option><option>Other</option></select></div><div class="vc-field"><label for="delivery-otp">Delivery OTP (if enabled)</label><input class="vc-input" id="delivery-otp" name="delivery_otp" inputmode="numeric" pattern="[0-9]{4,8}" maxlength="8" autocomplete="one-time-code"></div><div class="vc-field"><label for="cod-collected">COD collected (₹)</label><input class="vc-input" id="cod-collected" name="cod_collected" type="number" data-money min="0" max="10000000" step="0.01"></div><div class="vc-field full"><label for="outcome-note">Outcome/failure note</label><textarea class="vc-textarea" id="outcome-note" name="outcome_note" required minlength="10" maxlength="600"></textarea></div><div class="vc-field full"><label for="delivery-proof">Proof of delivery/attempt</label><input class="vc-input" id="delivery-proof" name="delivery_proof" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" data-max-bytes="5242880" required></div><div class="vc-field full"><label class="vc-check"><input name="confirm_outcome" type="checkbox" required> I confirm this outcome is accurate and supported by the uploaded evidence.</label></div></div><div class="vc-form-actions"><button class="vc-btn primary" type="submit">Validate outcome</button></div></form></dialog>